function overlaps(a, b) {
  return a.start < b.end && b.start < a.end;
}

function findAvailable(bikes, bookings, want) {
  // One pass over bookings: collect ids of bikes that clash with the wanted dates.
  const busy = new Set();
  for (const k of bookings) {
    if (overlaps(k, want)) busy.add(k.bikeId);
  }
  return bikes
    .filter(b => !busy.has(b.id))
    .sort((a, b) => a.pricePerDay - b.pricePerDay || a.id - b.id);
}

module.exports = { findAvailable };
EOF
